import{_ as l,E as o,h as c,c as d,b as e,f as t,H as r,a4 as s,w as p}from"./chunks/framework.B_fYP6Of.js";const v=JSON.parse('{"title":"AI models, tokens and your budget","description":"Estimate a small RAG app’s token bill with seven worked price examples. Compare two models on citation quality, retries, latency and cost per usable answer.","frontmatter":{"title":"AI models, tokens and your budget","description":"Estimate a small RAG app’s token bill with seven worked price examples. Compare two models on citation quality, retries, latency and cost per usable answer.","teaser":"One answer can trigger several paid calls. Follow a single request from retrieved passages to the bill, then see which costs scale with a class."},"headers":[],"relativePath":"students/ai-costs.md","filePath":"students/ai-costs.md"}'),u={name:"students/ai-costs.md"};function h(g,a,m,f,b,y){const n=o("LabArticleHeader"),i=o("LabScroll");return c(),d("div",null,[a[1]||(a[1]=e("h1",{id:"good-answers-small-budget-no-surprises",tabindex:"-1"},[t("Good answers. Small budget. No surprises. "),e("a",{class:"header-anchor",href:"#good-answers-small-budget-no-surprises","aria-label":'Permalink to "Good answers. Small budget. No surprises."'},"​")],-1)),r(n),a[2]||(a[2]=s('<p>Suppose your app sends 3,000 input tokens and uses 500 billed output tokens. At illustrative prices of $0.10 per million input tokens and $0.40 per million output tokens, that’s $0.00030 for input plus $0.00020 for output. One call costs $0.00050 at those rates. A thousand identical calls cost $0.50.</p><p>If you already have a usage record, compare its input and output counts with your estimate. Which count changed? Look at the passages your app sent and whether the request ran more than once. If you haven’t made a call, you can do the estimate on paper.</p><p><strong>For the IS373 project</strong>, the <a href="./reference">local retrieval exercise</a> works without an API key. Use Groq as a starting point for a small public-data generation experiment, or consider Gemini. Hosted generation is optional practice on this page. Check which provider adapters your application implements before choosing one.</p><p><a href="#compare-actual-models-not-company-names">See the example model prices</a> · <a href="#read-your-bill-before-you-grow-it">Calculate one request</a> · <a href="#keep-the-budget-and-the-key-under-control">Set limits</a></p><h2 id="choose-a-starting-point" tabindex="-1">Choose a starting point <a class="header-anchor" href="#choose-a-starting-point" aria-label="Permalink to &quot;Choose a starting point&quot;">​</a></h2><ul><li><strong>Groq:</strong> check which hosted models and allowances your account can use for an interactive experiment. Groq hosts models; <code>openai/gpt-oss-20b</code> on Groq is not a ChatGPT subscription or an OpenAI API bill.</li><li><strong>Gemini:</strong> check whether the selected model offers a free API option for your permitted public or synthetic material. Check the data terms before uploading anything.</li><li><strong>OpenAI, Anthropic and DeepSeek:</strong> useful comparison candidates when you have API access and a small approved budget. Don&#39;t assume that a free chatbot account supplies free API calls.</li></ul><p>Try the same five source-backed questions with two models. Record citation correctness, unsupported claims, latency and <strong>cost per acceptable answer</strong>. A higher price alone does not prove higher quality.</p><h2 id="compare-actual-models-not-company-names" tabindex="-1">Compare actual models, not company names <a class="header-anchor" href="#compare-actual-models-not-company-names" aria-label="Permalink to &quot;Compare actual models, not company names&quot;">​</a></h2><p><strong>Illustrative rates in USD per million tokens.</strong> These figures are worked budgeting examples. To estimate a real bill, replace the sample rates with current prices from the linked provider pages. The calculations assume standard text generation and uncached input, and exclude batch discounts, taxes, hosting, embeddings, and tools.</p><p><em>On a narrow screen, swipe the table sideways to see all prices.</em></p>',10)),r(i,{kind:"table",label:"table for Compare actual models, not company names"},{default:p(()=>[...a[0]||(a[0]=[e("table",{tabindex:"0"},[e("thead",null,[e("tr",null,[e("th",{scope:"col"},"Provider and example model"),e("th",{style:{"text-align":"right"},scope:"col"},"Input / 1M"),e("th",{style:{"text-align":"right"},scope:"col"},"Output / 1M"),e("th",{style:{"text-align":"right"},scope:"col"},"1,000 example answers*")])]),e("tbody",null,[e("tr",null,[e("td",null,[e("a",{href:"https://console.groq.com/docs/models",target:"_blank",rel:"noreferrer"},[t("Groq: "),e("code",null,"openai/gpt-oss-20b")])]),e("td",{style:{"text-align":"right"}},"$0.075"),e("td",{style:{"text-align":"right"}},"$0.30"),e("td",{style:{"text-align":"right"}},"$0.375")]),e("tr",null,[e("td",null,[e("a",{href:"https://console.groq.com/docs/models",target:"_blank",rel:"noreferrer"},[t("Groq: "),e("code",null,"openai/gpt-oss-120b")])]),e("td",{style:{"text-align":"right"}},"$0.15"),e("td",{style:{"text-align":"right"}},"$0.60"),e("td",{style:{"text-align":"right"}},"$0.75")]),e("tr",null,[e("td",null,[e("a",{href:"https://aistudio.google.com/docs/pricing#gemini-2.5-flash-lite",target:"_blank",rel:"noreferrer"},[t("Google: "),e("code",null,"gemini-2.5-flash-lite")])]),e("td",{style:{"text-align":"right"}},"$0.10"),e("td",{style:{"text-align":"right"}},"$0.40"),e("td",{style:{"text-align":"right"}},"$0.50")]),e("tr",null,[e("td",null,[e("a",{href:"https://developers.openai.com/api/docs/models/gpt-5.4-mini",target:"_blank",rel:"noreferrer"},[t("OpenAI: "),e("code",null,"gpt-5.4-mini")])]),e("td",{style:{"text-align":"right"}},"$0.75"),e("td",{style:{"text-align":"right"}},"$4.50"),e("td",{style:{"text-align":"right"}},"$4.50")]),e("tr",null,[e("td",null,[e("a",{href:"https://platform.claude.com/docs/en/about-claude/pricing",target:"_blank",rel:"noreferrer"},[t("Anthropic: "),e("code",null,"claude-haiku-5-5")])]),e("td",{style:{"text-align":"right"}},"$0.10"),e("td",{style:{"text-align":"right"}},"$0.50"),e("td",{style:{"text-align":"right"}},"$0.55")]),e("tr",null,[e("td",null,[e("a",{href:"https://api-docs.deepseek.com/quick_start/pricing/",target:"_blank",rel:"noreferrer"},[t("DeepSeek: "),e("code",null,"deepseek-flash"),t(", peak")])]),e("td",{style:{"text-align":"right"}},"$0.30"),e("td",{style:{"text-align":"right"}},"$1.20"),e("td",{style:{"text-align":"right"}},"$1.50")]),e("tr",null,[e("td",null,[e("a",{href:"https://api-docs.deepseek.com/quick_start/pricing/",target:"_blank",rel:"noreferrer"},[t("DeepSeek: "),e("code",null,"deepseek-flash"),t(", off-peak")])]),e("td",{style:{"text-align":"right"}},"$0.15"),e("td",{style:{"text-align":"right"}},"$0.60"),e("td",{style:{"text-align":"right"}},"$0.75")])])],-1)])]),_:1}),a[3]||(a[3]=s(`<p>*Each answer uses <strong>3,000 input + 500 total billed output tokens</strong>. This is a calculation, not measured performance or a promise about how many visible words you receive. Different tokenizers can count the same text differently; measure real usage when comparing providers.</p><p><strong>Which rate applies?</strong> The Haiku example assumes a prompt of up to 100,000 tokens. Longer prompts can fall into another price tier. A provider can also change the model behind an alias or apply peak rates, off-peak rates, regional charges, cache fees, and tool fees. Look up the model ID and conditions for your account. For a conservative estimate, use the highest applicable rate.</p><h2 id="what-does-free-actually-mean" tabindex="-1">What does “free” actually mean? <a class="header-anchor" href="#what-does-free-actually-mean" aria-label="Permalink to &quot;What does “free” actually mean?&quot;">​</a></h2><p><strong>Groq.</strong> Open the <a href="https://console.groq.com/docs/rate-limits" target="_blank" rel="noreferrer">rate limits</a> and your account console. Compare the organization’s requests-per-minute limit with its tokens-per-minute limit. A 3,500-token request can exhaust the token allowance well before the request allowance. Queue calls; respect <code>429</code> and retry guidance rather than creating accounts to bypass limits.</p><p><strong>Gemini.</strong> Check the selected Flash-Lite model’s pricing, rate limits, and data-use terms. Free and paid tiers can handle submitted content differently. Free access is not permission to upload classmates&#39; work or private records.</p><p><strong>OpenAI.</strong> Check whether your account has an API allowance for the model you want to use. ChatGPT is the user-facing app; the API powers your code. Treat billing separately. Some eligible subscriptions have a limited <a href="https://help.openai.com/en/articles/20001626-api-credits-benefit-for-eligible-chatgpt-subscriptions" target="_blank" rel="noreferrer">API-credit benefit</a>; check eligibility and activation rather than assuming your plan covers it.</p><p><strong>Anthropic and DeepSeek:</strong> budget for paid API usage unless your account explicitly shows usable credits. Trials, grants or subscriber benefits are not a permanent free allowance. Check credit expiry and what happens when it runs out.</p><p>For <strong>every</strong> provider, review age/region eligibility, account permissions and current terms. Groq&#39;s <a href="https://console.groq.com/docs/your-data" target="_blank" rel="noreferrer">data policy</a> distinguishes default inference handling from retention for certain features, reliability and abuse monitoring. “Not used for training” and “never stored” are different promises. Use public/synthetic documents for this lab.</p><h2 id="read-your-bill-before-you-grow-it" tabindex="-1">Read your bill before you grow it <a class="header-anchor" href="#read-your-bill-before-you-grow-it" aria-label="Permalink to &quot;Read your bill before you grow it&quot;">​</a></h2><p>A token is a small piece of text, not necessarily a word. Code, punctuation and different languages tokenize differently. Use the provider&#39;s tokenizer or response usage counts, not a word-count guess.</p><ul><li><strong>Input:</strong> instructions + question + conversation history + retrieved passages + tool schemas/results.</li><li><strong>Output:</strong> generated tokens, including billed reasoning/thinking where applicable. A short visible reply can still consume more.</li><li><strong>Context window:</strong> how much a request can hold, not a free allowance or a target to fill.</li><li><strong>Rate limit:</strong> how quickly you can call the service. A low price does not prevent throttling.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cost = input_tokens / 1,000,000 × input_price</span></span>
<span class="line"><span>     + billed_output_tokens / 1,000,000 × output_price</span></span>
<span class="line"><span>     + separately billed tools, storage and other services</span></span></code></pre></div><p>For Groq 20B, one example costs <code>3000/1M × $0.075 + 500/1M × $0.30 = $0.000375</code>. That is <strong>0.0375 cents</strong>, not 0.375 dollars. At 1,000 calls, it is <strong>$0.375</strong> before other charges. Free-tier eligibility may reduce the actual generation bill to zero, but not remove quotas.</p><p>A class of 30 students testing 100 times each makes 3,000 calls: <strong>$1.125</strong> at that paid rate. Three model calls per answer triples the estimate to <strong>$3.375</strong>; doubling again for retries and evaluation makes it <strong>$6.75</strong>. This is planning math, not a shared-key recommendation.</p><p>For a product, start with <code>active users × answers/user × calls/answer</code>. Add embeddings, hosting, storage, support and payment fees. A $10 hosting bill may exceed token costs in a small demo. Track cost per successful answer and reserve room for failures before choosing a selling price.</p><h2 id="can-graphs-or-vectors-lower-the-token-bill" tabindex="-1">Can graphs or vectors lower the token bill? <a class="header-anchor" href="#can-graphs-or-vectors-lower-the-token-bill" aria-label="Permalink to &quot;Can graphs or vectors lower the token bill?&quot;">​</a></h2><p>Start with the text your app actually put in the request. A vector is a numeric representation used to find similar content; a graph stores entities and relationships you can traverse. Usually the model receives selected text or serialized facts, not the entire database or its vector index. That text still becomes input tokens.</p><p>Think of <strong>useful evidence per token</strong>, rather than a universal “density of meaning” score. A compact graph fact such as <code>Course A → requires → Course B</code> can replace a long irrelevant passage, but may omit the exception, date or source that makes the fact true. Keep provenance and retrieve the supporting passage when needed. Graph construction, summaries and embeddings can themselves cost money; stale or incorrect summaries can make cheap answers worse.</p><p><strong>Illustrative comparison:</strong> suppose a long-context approach sends 20,000 input tokens per question, while targeted retrieval sends 3,000. At the sample Groq 20B input rate, that is $1.50 versus $0.225 for 1,000 questions: <strong>$1.275 saved on input</strong>, holding output fixed. These are assumed token counts, not a benchmark proving graph search beats vector search. A good SQL filter may save just as much. If building the index costs more than the savings, a tiny demo may never break even.</p><p>Compare SQL filters, keyword search, vector search, graph traversal and combinations on the <strong>same questions and source snapshot</strong>. Measure retrieval quality, citation accuracy, input/output tokens, indexing cost, latency and abstention when evidence is missing. Count only correct, adequately supported answers as successes. <a href="./data-choices">Choose a database and retrieval approach</a>.</p><h2 id="keep-the-budget-and-the-key-under-control" tabindex="-1">Keep the budget and the key under control <a class="header-anchor" href="#keep-the-budget-and-the-key-under-control" aria-label="Permalink to &quot;Keep the budget and the key under control&quot;">​</a></h2><ol><li>Start with a tiny request and inspect its actual usage. Set a small spending limit where supported and alerts before it. An alert is not necessarily a hard stop.</li><li>Enforce server-side limits on prompt size, retrieved chunks, output tokens, concurrent requests and calls per user. Limit agent iterations and retries. Require authentication and abuse controls before exposing a paid generation endpoint. Never silently switch from free to paid.</li><li>Keep keys on your server in ignored environment files or deployment secrets. Ignore secret files using both <code>.gitignore</code> and <code>.dockerignore</code>; a Git ignore rule does not stop Docker <code>COPY</code>. Never put them in Git, screenshots, frontend JavaScript, <code>VITE_*</code> variables, Docker images or Pages. Rotate an exposed key immediately.</li><li>Keep one provider adapter behind your application&#39;s interface. Configure provider/model on the server. Test differences in streaming, tools, JSON, token accounting and errors; “OpenAI-compatible” does not mean identical.</li><li>Log model/version, usage, latency and estimated cost, not secrets or sensitive prompt text. Compare logs with the billing dashboard.</li></ol><p><strong>Try it with five questions.</strong> Mark which answers contain a claim the cited passage supports. Divide the cost of <em>all</em> attempts by the number of acceptable answers. If four answers qualify and all five attempts cost $0.02, each acceptable answer cost $0.005. If none qualify, record the spend and zero successes. Then halve the retrieved context and repeat the same questions.</p><p>If the estimate and dashboard disagree, check the model ID, recorded input and billed output, calls per answer, and retry count before changing providers. You can do the arithmetic on paper. Use this comparison when it helps your project.</p>`,24))])}const w=l(u,[["render",h]]);export{v as __pageData,w as default};
